module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

    typedef enum logic [3:0] {
        S_A       = 4'd0,
        S_F       = 4'd1,
        S_X_NONE  = 4'd2,
        S_X_S1    = 4'd3,
        S_X_S10   = 4'd4,
        S_Y_WAIT1 = 4'd5,
        S_Y_WAIT2 = 4'd6,
        S_G_PERM1 = 4'd7,
        S_G_PERM0 = 4'd8
    } state_t;

    state_t state, next_state;

    // State transition logic
    always_ff @(posedge clk) begin
        if (!resetn) begin
            state <= S_A;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state = state;
        case (state)
            S_A: begin
                next_state = S_F;
            end
            S_F: begin
                next_state = S_X_NONE;
            end
            S_X_NONE: begin
                if (x) next_state = S_X_S1;
                else   next_state = S_X_NONE;
            end
            S_X_S1: begin
                if (x)     next_state = S_X_S1;
                else       next_state = S_X_S10;
            end
            S_X_S10: begin
                if (x)     next_state = S_Y_WAIT1;
                else       next_state = S_X_NONE;
            end
            S_Y_WAIT1: begin
                if (y)     next_state = S_G_PERM1;
                else       next_state = S_Y_WAIT2;
            end
            S_Y_WAIT2: begin
                if (y)     next_state = S_G_PERM1;
                else       next_state = S_G_PERM0;
            end
            S_G_PERM1: begin
                next_state = S_G_PERM1;
            end
            S_G_PERM0: begin
                next_state = S_G_PERM0;
            end
            default: begin
                next_state = S_A;
            end
        endcase
    end

    // Output logic
    always_comb begin
        f = 0;
        g = 0;
        case (state)
            S_F: begin
                f = 1;
                g = 0;
            end
            S_Y_WAIT1, S_Y_WAIT2, S_G_PERM1: begin
                f = 0;
                g = 1;
            end
            S_G_PERM0: begin
                f = 0;
                g = 0;
            end
            default: begin
                f = 0;
                g = 0;
            end
        endcase
    end

endmodule

